INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(33961, 'Job 12:10', 'Job', 12, 10, 'د هغۀ په لاس کښې د هر ژوندى څيز ژوند دے او د هغۀ په لاس کښې د هر بشر ساه ده.', 'د هغۀ په لاس کشې د هر ژوندی چیز ژوند دے او د هغۀ په لاس کشې د هر بشر ساه ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33962, 'Job 12:11', 'Job', 12, 11, 'ولې غوږونه د خبرو معائنه نۀ کوى لکه څنګه چې ژبه د خوراک خوند معلوموى؟', 'ولې غوزونه د خبرو معاینه نۀ کوی لکه چنګه چې ژبه د خوراک خوند معلوموی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33963, 'Job 12:12', 'Job', 12, 12, 'ولې حِکمت د سپين‌ږيرو سره نۀ وى څۀ؟ ولې زيات عُمر سره پوهه نۀ راځى څۀ؟', 'ولې حکمت د سپین‌زیرو سره نۀ وی چۀ؟ ولې زیات عمر سره پوهه نۀ راجی چۀ؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33964, 'Job 12:13', 'Job', 12, 13, 'حِکمت او طاقت د خُدائ پاک سره دى، د هغۀ سره رهنمائى او پوهه شته دے.', 'حکمت او طاقت د خدای پاک سره دی، د هغۀ سره رهنمایی او پوهه شته دے.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33965, 'Job 12:14', 'Job', 12, 14, 'چې هغه څۀ وران کړى نو هيڅ څوک يې بيا نۀ شى جوړولے، او چې هغه کوم سړے قېدى کړى نو هغه خلاصېدلے نۀ شى.', 'چې هغه چۀ وران کری نو هیچ چوک یې بیا نۀ شی جورولے، او چې هغه کوم سرے قېدی کری نو هغه خلاصېدلے نۀ شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33966, 'Job 12:15', 'Job', 12, 15, 'کۀ هغه باران ايسار کړى، نو زمکه به اوچه شى، کۀ هغه اوبۀ راپرېږدى، نو اوبۀ به زمکه تباه کړى.', 'کۀ هغه باران ایسار کری، نو زمکه به اوچه شی، کۀ هغه اوبۀ راپرېزدی، نو اوبۀ به زمکه تباه کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33967, 'Job 12:16', 'Job', 12, 16, 'طاقت او حِکمت د هغۀ سره دے، دوکه خوړونکے او دوکه ورکوونکے د هغۀ د اختيار لاندې دى.', 'طاقت او حکمت د هغۀ سره دے، دوکه خورونکے او دوکه ورکوونکے د هغۀ د اختیار لاندې دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33968, 'Job 12:17', 'Job', 12, 17, 'هغه د مشرانو نه پوهه اخلى، او د قاضيانو نه کم عقلان جوړوى.', 'هغه د مشرانو نه پوهه اخلی، او د قاضیانو نه کم عقلان جوروی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33969, 'Job 12:18', 'Job', 12, 18, 'هغه د بادشاهانو نه اختيار واخلى، او د هغوئ نه غلامان جوړ کړى.', 'هغه د بادشاهانو نه اختیار واخلی، او د هغوی نه غلامان جور کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33970, 'Job 12:19', 'Job', 12, 19, 'هغه اِمامان شړى او اختيار ترې اخلى، او هغه طاقتور لرې کوى چې ډېر وخت يې حکومت کړے وى.', 'هغه امامان شری او اختیار ترې اخلی، او هغه طاقتور لرې کوی چې دېر وخت یې حکومت کرے وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33971, 'Job 12:20', 'Job', 12, 20, 'هغه اعتبارى مشيران غلى کړى، د مشرانو نه حِکمت يوسى.', 'هغه اعتباری مشیران غلی کری، د مشرانو نه حکمت یوسی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33972, 'Job 12:21', 'Job', 12, 21, 'هغه شهزادګان سپک کړى، او هغه د زورَورو زور اوبۀ کوى.', 'هغه شهزادګان سپک کری، او هغه د زورورو زور اوبۀ کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33973, 'Job 12:22', 'Job', 12, 22, 'هغه د قبر تيارۀ لرې کوى، او هغه تکه توره تيارۀ په رڼا بدلوى.', 'هغه د قبر تیارۀ لرې کوی، او هغه تکه توره تیارۀ په رنا بدلوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33974, 'Job 12:23', 'Job', 12, 23, 'هغه قومونه تکړه کړى او بيا يې تباه کړى، هغه قومونه لوئ کړى او بيا يې پرېږدى.', 'هغه قومونه تکره کری او بیا یې تباه کری، هغه قومونه لوی کری او بیا یې پرېزدی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33975, 'Job 12:24', 'Job', 12, 24, 'هغه د دُنيا د مشرانو نه پوهه ختموى، او پرې يې ږدى چې سرګردانه او پرېشانه ګرځى.', 'هغه د دنیا د مشرانو نه پوهه ختموی، او پرې یې زدی چې سرګردانه او پرېشانه ګرجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33976, 'Job 12:25', 'Job', 12, 25, 'هغه مشران په تيارۀ کښې د ړندو په شان سرګردانه ګرځى، او د شرابى په شان يې ځنګېدلے کړى.', 'هغه مشران په تیارۀ کشې د رندو په شان سرګردانه ګرجی، او د شرابی په شان یې جنګېدلے کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Job_12_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33977, 'Isaiah 66:1', 'Isaiah', 66, 1, 'څښتن داسې وایي: «اسمان زما تخت دی او ځمکه زما د پښو چوکۍ ده. تاسو به ماته څه ډول کور جوړ کړئ او زما د اوسېدلو ځای چېرته دی؟', 'چشتن داسې وایی: «اسمان زما تخت دی او جمکه زما د پشو چوکی ده. تاسو به ماته چه دول کور جور کری او زما د اوسېدلو جای چېرته دی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah066_verse_001.mp3', 'https://drive.google.com/file/d/1k9RTTVgL1PGAp3_FDwnd-GyyEjkHX8Y0/preview', 1761237837, 1761237837),
(33978, 'Isaiah 66:2', 'Isaiah', 66, 2, 'ما دا ټول شیان په خپل لاس پیدا کړل او هغه منځ ته راغلل. خو زه د هغه چا سره یم چې عاجز او توبه کوونکی وي او زما د کلام په وړاندې له وېرې رېږدي.', 'ما دا تول شیان په خپل لاس پیدا کرل او هغه منج ته راغلل. خو زه د هغه چا سره یم چې عاجز او توبه کوونکی وی او زما د کلام په وراندې له وېرې رېزدی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah066_verse_002.mp3', 'https://drive.google.com/file/d/1BEbtPvlmbC916Ib5dG4ElHYoJirWFjC6/preview', 1761237837, 1761237837),
(33979, 'Isaiah 66:3', 'Isaiah', 66, 3, 'څوک چې د قربانۍ دپاره غویی حلالوي، هغه انسان هم قتلوي. څوک چې وری د قربانۍ دپاره حلالوي، هغه د سپي ورمېږ هم ماتوي. څوک چې د غلو دانو نذرانې ماته راوړي، هغه د خوګ وینه هم وړاندې کوي. څوک چې ماته قیمتي خوشبویي سوځوي، هغه بت ته هم عبادت کوي. څنګه چې د هغوی زړه وغواړي، هماغه کار کوي. هغوی د هغو ناوړو کارونو څخه چې د کرکې وړ دي، خوند اخلي.', 'چوک چې د قربانی دپاره غویی حلالوی، هغه انسان هم قتلوی. چوک چې وری د قربانی دپاره حلالوی، هغه د سپی ورمېز هم ماتوی. چوک چې د غلو دانو نذرانې ماته راوری، هغه د خوګ وینه هم وراندې کوی. چوک چې ماته قیمتی خوشبویی سوجوی، هغه بت ته هم عبادت کوی. چنګه چې د هغوی زره وغواری، هماغه کار کوی. هغوی د هغو ناورو کارونو چخه چې د کرکې ور دی، خوند اخلی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah066_verse_003.mp3', 'https://drive.google.com/file/d/1xYI_QZfS4PAoez6vnvzhBNfT-AFPYRcr/preview', 1761237837, 1761237837),
(33980, 'Isaiah 66:4', 'Isaiah', 66, 4, 'نو زه به هم د هغوی دپاره سخت مصیبت وغواړم، داسې مصیبت چې هغوی ورنه وېریږي. ځکه کله چې ما په هغوی غږ وکړ، نو هېچا ځواب رانه کړ او کله به چې ما خبرې کولې، نو هېچا به ورته غوږ نه نیوه. خو هغوی هغه کارونه وکړل چې زما په نظر بد وو او هغه څه یې خوښ کړل چې زه پرې خوشحاله نه وم.»', 'نو زه به هم د هغوی دپاره سخت مصیبت وغوارم، داسې مصیبت چې هغوی ورنه وېریزی. جکه کله چې ما په هغوی غز وکر، نو هېچا جواب رانه کر او کله به چې ما خبرې کولې، نو هېچا به ورته غوز نه نیوه. خو هغوی هغه کارونه وکرل چې زما په نظر بد وو او هغه چه یې خوش کرل چې زه پرې خوشحاله نه وم.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah066_verse_004.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1qMvL7ZotK7Sskk2hUI6aQzinZ_Ca7EzN&export=download', 1761237837, 1761237837),
(33981, 'Isaiah 66:5', 'Isaiah', 66, 5, 'ای هغو خلکو چې د څښتن د کلام څخه لړزېږئ، د هغه کلام ته غوږ ونیسئ چې وایي: «زما د نوم په خاطر ستاسو خپل خلک ستاسو نه کرکه کوي او تاسې شړي. هغوی په ملنډو تاسو ته وایي: ‹څښتن دې خپله لویي وښایي او تاسو دې وژغوري، ترڅو مونږ ستاسو خوشحالي ووینو!› خو هغوی به په خپله رسوا شي او وبه شرمیږي.', 'ای هغو خلکو چې د چشتن د کلام چخه لرزېزی، د هغه کلام ته غوز ونیسی چې وایی: «زما د نوم په خاطر ستاسو خپل خلک ستاسو نه کرکه کوی او تاسې شری. هغوی په ملندو تاسو ته وایی: ‹چشتن دې خپله لویی وشایی او تاسو دې وژغوری، ترچو مونز ستاسو خوشحالی ووینو!› خو هغوی به په خپله رسوا شی او وبه شرمیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah066_verse_005.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1f9fAhud1igUoWS7fU9Nf4jxkUijrLG3O&export=download', 1761237837, 1761237837),
(33982, 'Isaiah 66:6', 'Isaiah', 66, 6, 'واورئ! هغه شورماشور چې له ښار څخه راځي او هغه غوغا چې د عبادت د ځای څخه اورېدل کیږي، دا د څښتن اواز دی چې د خپلو دښمنانو څخه بدل اخلي.', 'واوری! هغه شورماشور چې له شار چخه راجی او هغه غوغا چې د عبادت د جای چخه اورېدل کیزی، دا د چشتن اواز دی چې د خپلو دشمنانو چخه بدل اخلی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah066_verse_006.mp3', 'https://drive.google.com/file/d/1a0g3ZS40BGqTa0QbTmWChRvwBwnq5jcp/preview', 1761237837, 1761237837),
(33983, 'Isaiah 66:7', 'Isaiah', 66, 7, 'زما سپېڅلی ښار د هغې ښځې په شان دی چې ماشوم یې د زېږېدو له درد نه مخکې وزېږیږي، د لنګون له درد نه مخکې یې ناڅاپه زوی دې نړۍ ته راځي.', 'زما سپېچلی شار د هغې شجې په شان دی چې ماشوم یې د زېزېدو له درد نه مخکې وزېزیزی، د لنګون له درد نه مخکې یې ناچاپه زوی دې نری ته راجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah066_verse_007.mp3', 'https://drive.google.com/file/d/1Q9twDTuJFBUSTQIdSwGye1kUiETRHDKz/preview', 1761237837, 1761237837),
(33984, 'Isaiah 66:8', 'Isaiah', 66, 8, 'ایا چا کله داسې حیرانوونکې پېښه لیدلې یا اورېدلې ده چې ناڅاپه یو هېواد په یوه ورځ کې پیدا شي؟ ایا کوم قوم په یوه شېبه کې زېږېدلی شي؟ خو په هغه شېبه کې چې په صهیون باندې د لنګون درد پیل شو، ماشومان یې دې نړۍ ته راوړل.', 'ایا چا کله داسې حیرانوونکې پېشه لیدلې یا اورېدلې ده چې ناچاپه یو هېواد په یوه ورج کې پیدا شی؟ ایا کوم قوم په یوه شېبه کې زېزېدلی شی؟ خو په هغه شېبه کې چې په صهیون باندې د لنګون درد پیل شو، ماشومان یې دې نری ته راورل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah066_verse_008.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1SmqLYowriF74lEvRjuI0f3UXKiyXJjcM&export=download', 1761237837, 1761237837),
(33985, 'Isaiah 66:9', 'Isaiah', 66, 9, 'ایا فکر کوئ کله چې زه د یوې ښځې خېټه خلاصه کړم او په همدې شېبه کې یې پرېنږدم چې ماشوم یې وزېږیږي؟ نه، زه هېڅکله داسې کار نه کوم.» ستاسو څښتن خدای داسې ویلي دي:', 'ایا فکر کوی کله چې زه د یوې شجې خېته خلاصه کرم او په همدې شېبه کې یې پرېنزدم چې ماشوم یې وزېزیزی؟ نه، زه هېچکله داسې کار نه کوم.» ستاسو چشتن خدای داسې ویلی دی:', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah066_verse_009.mp3', 'https://drive.google.com/file/d/1ng_qESH62q0FuRDRHS85HBLD3e8Btkx7/preview', 1761237837, 1761237837),
